import{_ as s,C as e,o as n,c as d,a2 as r,j as a,E as l,a as o}from"./chunks/framework.C21TwvGF.js";const F=JSON.parse('{"title":"25-dars (Mentor). 25-dars: Flowalgorithmda tarmoqlanuvchi algoritmlar va shartlar bilan ishlash (1-dars)","description":"","frontmatter":{"title":"25-dars (Mentor). 25-dars: Flowalgorithmda tarmoqlanuvchi algoritmlar va shartlar bilan ishlash (1-dars)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":9,"link":"/mentor/8-sinf-cs/hafta-09/"},"g":25,"title":"25-dars: Flowalgorithmda tarmoqlanuvchi algoritmlar va shartlar bilan ishlash (1-dars)","lead":"Flowalgorithmda tarmoqlanuvchi algoritmlar va shartlar bilan ishlash","slide":"/slaydlar/8-sinf-cs/hafta-09/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-09/dars-1-test.html","student_link":"/8-sinf-cs/hafta-09/dars-1","tabs":[{"g":25,"link":"/mentor/8-sinf-cs/hafta-09/dars-1","current":true},{"g":26,"link":"/mentor/8-sinf-cs/hafta-09/dars-2","current":false},{"g":27,"link":"/mentor/8-sinf-cs/hafta-09/dars-3","current":false}],"prev":null,"next":{"g":26,"title":"26-dars: Flowalgorithmda tarmoqlanuvchi algoritmlar va shartlar bilan ishlash (2-dars)","link":"/mentor/8-sinf-cs/hafta-09/dars-2"}}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-09/dars-1.md","filePath":"mentor/8-sinf-cs/hafta-09/dars-1.md"}'),h={name:"mentor/8-sinf-cs/hafta-09/dars-1.md"},u={class:"blk"},c={id:"dars-rejasi",tabindex:"-1"},m={class:"blk"},g={id:"mentor-konspekti",tabindex:"-1"},k={class:"blk"},q={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},b={class:"blk"},p={id:"tezkor-nazorat-savollari",tabindex:"-1"},y={class:"blk"},f={id:"uyga-vazifa",tabindex:"-1"};function v(_,i,T,z,x,I){const t=e("Icon");return n(),d("div",null,[i[16]||(i[16]=r("<p><strong>Fan:</strong> Computer Science Foundation<br><strong>Sinf:</strong> 8-sinf<br><strong>Hafta:</strong> 9-hafta (1-dars)<br><strong>Davomiyligi:</strong> 80 daqiqa<br><strong>Format:</strong> Nazariy tushunchalar (25 daqiqa) + Kompyuterda laboratoriya va amaliyot (50 daqiqa) + Xulosa (5 daqiqa)</p><hr>",2)),a("div",u,[a("h2",c,[l(t,{name:"file-text"}),i[0]||(i[0]=o(" Dars rejasi ",-1)),i[1]||(i[1]=a("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),i[2]||(i[2]=r("<ol><li><strong>Tashkiliy qism va o&#39;tgan mavzuni takrorlash (10 daqiqa)</strong><ul><li>8-haftadagi chiziqli algoritmlar, arifmetik amallar va qavslar tartibini eslash.</li><li>Muammoli savol: «Agar dastur faqat bitta yo&#39;nalishda yursa, foydalanuvchining paroli to&#39;g&#39;ri yoki noto&#39;g&#39;riligini qanday tekshiramiz?»</li></ul></li><li><strong>Yangi mavzu: Tarmoqlanuvchi algoritmlar va Decision bloki (25 daqiqa)</strong><ul><li>Tarmoqlanuvchi algoritm tushunchasi — hayotiy chorrahalar va tanlov.</li><li>Flowgorithmda <code>Decision</code> (Shart / Qaror) bloki — Romb shakli.</li><li><code>True</code> (Rost / Ha) va <code>False</code> (Yolg&#39;on / Yo&#39;q) tarmoqlari.</li><li>Taqqoslash operatorlari: <ul><li><code>&gt;</code> (katta), <code>&lt;</code> (kichik)</li><li><code>&gt;=</code> (katta yoki teng), <code>&lt;=</code> (kichik yoki teng)</li><li><code>==</code> (tenglikni tekshirish, bitta <code>=</code> bilan adashtirmaslik!)</li><li><code>!=</code> (teng emas)</li></ul></li><li>Qoldiqli bo&#39;lish amali (<code>%</code>) va juft-toqlikni tekshirish mantig&#39;i.</li></ul></li><li><strong>Amaliy laboratoriya mashg&#39;uloti: Flowgorithmda shartli loyihalar (40 daqiqa)</strong><ul><li>1-loyiha: Musbat yoki manfiy sonni aniqlash (<code>son &gt; 0</code>).</li><li>2-loyiha: Juft yoki toq sonni aniqlash (<code>son % 2 == 0</code>).</li><li>3-loyiha: Ikkita sondan kattasini topish (Max).</li><li>4-loyiha: F6 (Step) yordamida shartning qaysi tarmoqqa burilishini vizual kuzatish.</li></ul></li><li><strong>Darsni yakunlash va baholash (5 daqiqa)</strong><ul><li>Tezkor nazorat savollari.</li><li>Uyga vazifani tushuntirish.</li></ul></li></ol><hr>",2))]),a("div",m,[a("h2",g,[l(t,{name:"file-text"}),i[3]||(i[3]=o(" Mentor konspekti ",-1)),i[4]||(i[4]=a("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),i[5]||(i[5]=r('<h3 id="_1-tarmoqlanuvchi-algoritm-branching-algorithm-nima" tabindex="-1">1. Tarmoqlanuvchi algoritm (Branching Algorithm) nima? <a class="header-anchor" href="#_1-tarmoqlanuvchi-algoritm-branching-algorithm-nima" aria-label="Permalink to &quot;1. Tarmoqlanuvchi algoritm (Branching Algorithm) nima?&quot;">​</a></h3><ul><li><strong>Ta&#39;rif:</strong> Berilgan shartning bajarilishi yoki bajarilmasligiga qarab, keyingi buyruqlar ketma-ketligi ikki yoki undan ortiq tarmoqlardan biri bo&#39;yicha davom etadigan algoritmga <strong>tarmoqlanuvchi algoritm</strong> deyiladi.</li><li><strong>Hayotiy misol:</strong> Svetofor qoidasi. <ul><li>Agar chiroq <em>Yashil</em> bo&#39;lsa (<code>True</code>) $\\rightarrow$ Yo&#39;ldan o&#39;tish.</li><li>Aks holda (<code>False</code>) $\\rightarrow$ To&#39;xtash va kutish.</li></ul></li></ul><h3 id="_2-flowgorithmda-decision-romb-bloki" tabindex="-1">2. Flowgorithmda Decision (Romb) bloki <a class="header-anchor" href="#_2-flowgorithmda-decision-romb-bloki" aria-label="Permalink to &quot;2. Flowgorithmda Decision (Romb) bloki&quot;">​</a></h3><p>Flowgorithmda shart tekshirish uchun <strong>sariq rangli Romb</strong> shaklidagi <code>Decision</code> bloki ishlatiladi.</p><ul><li>Romb ichiga faqat <strong>mantiqiy ifoda</strong> yoziladi (natijasi <code>true</code> yoki <code>false</code> bo&#39;ladigan ifoda).</li><li>Rombdan ikkita yo&#39;l chiqadi: <ul><li><strong>True (O&#39;ng/Chap tarmoq):</strong> Shart bajarilganda (rost bo&#39;lganda) ishlaydigan buyruqlar.</li><li><strong>False (Qarama-qarshi tarmoq):</strong> Shart bajarilmaganda (yolg&#39;on bo&#39;lganda) ishlaydigan buyruqlar.</li></ul></li></ul><h3 id="_3-taqqoslash-operatorlari-relational-operators" tabindex="-1">3. Taqqoslash operatorlari (Relational Operators) <a class="header-anchor" href="#_3-taqqoslash-operatorlari-relational-operators" aria-label="Permalink to &quot;3. Taqqoslash operatorlari (Relational Operators)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operator</th><th>Ma&#39;nosi</th><th>Misol</th><th>Natija ($a = 5$)</th></tr></thead><tbody><tr><td><code>&gt;</code></td><td>Katta</td><td><code>a &gt; 3</code></td><td><code>true</code></td></tr><tr><td><code>&lt;</code></td><td>Kichik</td><td><code>a &lt; 10</code></td><td><code>true</code></td></tr><tr><td><code>&gt;=</code></td><td>Katta yoki teng</td><td><code>a &gt;= 5</code></td><td><code>true</code></td></tr><tr><td><code>&lt;=</code></td><td>Kichik yoki teng</td><td><code>a &lt;= 4</code></td><td><code>false</code></td></tr><tr><td><code>==</code></td><td>Tengmi?</td><td><code>a == 5</code></td><td><code>true</code></td></tr><tr><td><code>!=</code></td><td>Teng emasmi?</td><td><code>a != 5</code></td><td><code>false</code></td></tr></tbody></table><blockquote><p><strong>O&#39;ta muhim qoida!</strong><br> Dasturlashda bitta tenglik (<code>=</code>) — bu <strong>o&#39;zlashtirish</strong> (Assign bloki).<br> Ikkita tenglik (<code>==</code>) — bu <strong>taqqoslash / tekshirish</strong> (Decision bloki).<br> Romb ichiga hech qachon bitta <code>=</code> yozilmaydi, faqat <code>==</code> yoziladi!</p></blockquote><h3 id="_4-juft-va-toq-sonlarni-tekshirish-siri-operatori" tabindex="-1">4. Juft va Toq sonlarni tekshirish siri (<code>%</code> operatori) <a class="header-anchor" href="#_4-juft-va-toq-sonlarni-tekshirish-siri-operatori" aria-label="Permalink to &quot;4. Juft va Toq sonlarni tekshirish siri (`%` operatori)&quot;">​</a></h3><p>Butun sonni 2 ga bo&#39;lgandagi qoldiq:</p><ul><li>Agar qoldiq 0 bo&#39;lsa $\\rightarrow$ Son <strong>juft</strong> (<code>son % 2 == 0</code>).</li><li>Aks holda $\\rightarrow$ Son <strong>toq</strong>.</li></ul><hr>',12))]),a("div",k,[a("h2",q,[l(t,{name:"file-text"}),i[6]||(i[6]=o(" Amaliy topshiriqlar va yechimlar ",-1)),i[7]||(i[7]=a("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),i[8]||(i[8]=r('<h3 id="_1-topshiriq-musbat-manfiy-yoki-nol-·-oson" tabindex="-1">1-topshiriq: Musbat, manfiy yoki nol · oson <a class="header-anchor" href="#_1-topshiriq-musbat-manfiy-yoki-nol-·-oson" aria-label="Permalink to &quot;1-topshiriq: Musbat, manfiy yoki nol · oson&quot;">​</a></h3><p>Foydalanuvchi bitta butun son kiritadi. Dastur son musbat yoki manfiy ekanligini aniqlasin.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Integer son</code></li><li><code>Output &quot;Son kiriting:&quot;</code></li><li><code>Input son</code></li><li><code>Decision son &gt;= 0</code><ul><li>True tarmog&#39;i: <code>Output &quot;Musbat yoki nol&quot;</code></li><li>False tarmog&#39;i: <code>Output &quot;Manfiy son&quot;</code></li></ul></li></ol><hr><h3 id="_2-topshiriq-juft-yoki-toq-son-·-oson" tabindex="-1">2-topshiriq: Juft yoki Toq son · oson <a class="header-anchor" href="#_2-topshiriq-juft-yoki-toq-son-·-oson" aria-label="Permalink to &quot;2-topshiriq: Juft yoki Toq son · oson&quot;">​</a></h3><p>Foydalanuvchi kiritgan son juft yoki toq ekanini aniqlovchi blok-sxema tuzing.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Integer n</code></li><li><code>Output &quot;Son kiriting:&quot;</code></li><li><code>Input n</code></li><li><code>Decision n % 2 == 0</code><ul><li>True tarmog&#39;i: <code>Output n &amp; &quot; — Juft son&quot;</code></li><li>False tarmog&#39;i: <code>Output n &amp; &quot; — Toq son&quot;</code></li></ul></li></ol><hr><h3 id="_3-topshiriq-ikkita-sondan-kattasi-max-·-o-rta" tabindex="-1">3-topshiriq: Ikkita sondan kattasi (Max) · o&#39;rta <a class="header-anchor" href="#_3-topshiriq-ikkita-sondan-kattasi-max-·-o-rta" aria-label="Permalink to &quot;3-topshiriq: Ikkita sondan kattasi (Max) · o&#39;rta&quot;">​</a></h3><p>Foydalanuvchi ikkita turli son kiritadi ($a$ va $b$). Dastur qaysi biri katta ekanligini aniqlab ekranga chiqarsin.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Real a, b</code></li><li><code>Output &quot;Ikkita son kiriting:&quot;</code></li><li><code>Input a</code></li><li><code>Input b</code></li><li><code>Decision a &gt; b</code><ul><li>True tarmog&#39;i: <code>Output &quot;Katta son: &quot; &amp; a</code></li><li>False tarmog&#39;i: <code>Output &quot;Katta son: &quot; &amp; b</code></li></ul></li></ol><hr><h3 id="_4-topshiriq-imtihondan-o-tish-tekshiruvi-·-o-rta" tabindex="-1">4-topshiriq: Imtihondan o&#39;tish tekshiruvi · o&#39;rta <a class="header-anchor" href="#_4-topshiriq-imtihondan-o-tish-tekshiruvi-·-o-rta" aria-label="Permalink to &quot;4-topshiriq: Imtihondan o&#39;tish tekshiruvi · o&#39;rta&quot;">​</a></h3><p>O&#39;quvchi imtihon balini kiritadi (0 dan 100 gacha). Agar ball 60 yoki undan yuqori bo&#39;lsa, <code>&quot;Tabriklaymiz, siz o&#39;tdingiz!&quot;</code>, aks holda <code>&quot;Afsuski, yiqildingiz. Qayta topshirish kerak.&quot;</code> deb chiqarsin.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Integer ball</code></li><li><code>Output &quot;Imtihon balingizni kiriting:&quot;</code></li><li><code>Input ball</code></li><li><code>Decision ball &gt;= 60</code><ul><li>True tarmog&#39;i: <code>Output &quot;Tabriklaymiz, siz o&#39;tdingiz!&quot;</code></li><li>False tarmog&#39;i: <code>Output &quot;Afsuski, yiqildingiz. Qayta topshirish kerak.&quot;</code></li></ul></li></ol><hr><h3 id="_5-topshiriq-do-kondagi-bepul-yetkazib-berish-·-qiyin" tabindex="-1">5-topshiriq: Do&#39;kondagi bepul yetkazib berish · qiyin <a class="header-anchor" href="#_5-topshiriq-do-kondagi-bepul-yetkazib-berish-·-qiyin" aria-label="Permalink to &quot;5-topshiriq: Do&#39;kondagi bepul yetkazib berish · qiyin&quot;">​</a></h3><p>Xarid summasi kiritiladi. Agar xarid 200 000 so&#39;m yoki undan ko&#39;p bo&#39;lsa, yetkazib berish bepul (0 so&#39;m), aks holda yetkazib berish narxi 20 000 so&#39;m. Yakuniy to&#39;lov summasini hisoblab chiqaring.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Real xarid, yetkazish, jami</code></li><li><code>Output &quot;Xarid summasini kiriting (so&#39;m):&quot;</code></li><li><code>Input xarid</code></li><li><code>Decision xarid &gt;= 200000</code><ul><li>True tarmog&#39;i: <code>Assign yetkazish = 0</code></li><li>False tarmog&#39;i: <code>Assign yetkazish = 20000</code></li></ul></li><li><code>Assign jami = xarid + yetkazish</code></li><li><code>Output &quot;Yetkazib berish: &quot; &amp; yetkazish &amp; &quot; so&#39;m. Jami to&#39;lov: &quot; &amp; jami &amp; &quot; so&#39;m&quot;</code></li></ol><hr>',25))]),a("div",b,[a("h2",p,[l(t,{name:"file-text"}),i[9]||(i[9]=o(" Tezkor nazorat savollari ",-1)),i[10]||(i[10]=a("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),i[11]||(i[11]=a("ol",null,[a("li",null,"Tarmoqlanuvchi algoritm chiziqli algoritmdan nimasi bilan farq qiladi?"),a("li",null,"Flowgorithmda shart tekshirish qaysi blok orqali bajariladi va uning shakli qanday?"),a("li",null,[o("Bitta tenglik ("),a("code",null,"="),o(") va ikkita tenglik ("),a("code",null,"=="),o(") o'rtasidagi farq nima?")]),a("li",null,"Juft sonni aniqlash uchun qaysi matematik operator va qanday shart ishlatiladi?"),a("li",null,"Decision blokining ikkala tarmog'i (True va False) bir vaqtda birdaniga ishlashi mumkinmi?")],-1)),i[12]||(i[12]=a("hr",null,null,-1))]),a("div",y,[a("h2",f,[l(t,{name:"house"}),i[13]||(i[13]=o(" Uyga vazifa ",-1)),i[14]||(i[14]=a("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),i[15]||(i[15]=a("ol",null,[a("li",null,"Uyga vazifa faylidagi 25-dars topshirig'ini Flowgorithmda bajarish."),a("li",null,"Foydalanuvchining yoshini so'rab, agar yoshi 18 dan kichik bo'lsa «Bolalar chiptasi», 18 va undan katta bo'lsa «Kattalar chiptasi» deb chiqaruvchi blok-sxema tuzish."),a("li",null,"F6 (Step) tugmasi bilan turli qiymatlar kiritib shartning qanday ishlashini sinab ko'rish.")],-1))])])}const A=s(h,[["render",v]]);export{F as __pageData,A as default};
